This example shows how to create an instance of the  class:

Dim currentSources As String() = {"CS1", "CS2"}
Dim voltageSources As String() = {"VS1", "VS2"}
Dim voltageMeters As String() = {"VM1", "VM2"}
Dim currentMeters As String() = {"CM1", "CM2"}
Dim laserController As New clsUniversalLaserController(currentSources, voltageSources, voltageMeters, currentMeters)
